(* [comment removed for export] *)
Lemma art_frepP_pnums : forall p, In p (art_live (g_log FSG G)) -> fst p <> mb ->
  0 <= fst p / 8 /\ (fst p + snd p) / 8 = fst p / 8 + snd p / 8 /\ fst p / 8 + snd p / 8 <= 2 ^ 44
